bool decode_message(Kind kind, Json& in, Message& out, DecodeError& e) {
  switch (kind) {
    case Kind::hello: {
      Hello m;
      if (!decode_hello(in, m, e)) {
        return false;
      }
      out = std::move(m);
      return true;
    }
    case Kind::welcome: {
      Welcome m;
      if (!decode_welcome(in, m, e)) {
        return false;
      }
      out = std::move(m);
      return true;
    }
    case Kind::sub: {
      Sub m;
      if (!decode_sub(in, m, e)) {
        return false;
      }
      out = std::move(m);
      return true;
    }
    case Kind::unsub: {
      Unsub m;
      if (!decode_unsub(in, m, e)) {
        return false;
      }
      out = std::move(m);
      return true;
    }
    case Kind::state: {
      State m;
      if (!decode_state(in, m, e)) {
        return false;
      }
      out = std::move(m);
      return true;
    }
    case Kind::rows: {
      Rows m;
      if (!decode_rows(in, m, e)) {
        return false;
      }
      out = std::move(m);
      return true;
    }
    case Kind::cmd: {
      Cmd m;
      if (!decode_cmd(in, m, e)) {
        return false;
      }
      out = std::move(m);
      return true;
    }
    case Kind::result: {
      Result m;
      if (!decode_result(in, m, e)) {
        return false;
      }
      out = std::move(m);
      return true;
    }
    case Kind::error: {
      Error m;
      if (!decode_error(in, m, e)) {
        return false;
      }
      out = std::move(m);
      return true;
    }
    case Kind::bye: {
      Bye m;
      if (!decode_bye(in, m, e)) {
        return false;
      }
      out = std::move(m);
      return true;
    }
    case Kind::ping: {
      Ping m;
      if (!decode_ping(in, m, e)) {
        return false;
      }
      out = std::move(m);
      return true;
    }
    case Kind::pong: {
      Pong m;
      if (!decode_pong(in, m, e)) {
        return false;
      }
      out = std::move(m);
      return true;
    }
  }
  return fail(e, "t", "not a kind");
}

Json encode_message(const Message& message) {
  return std::visit([](const auto& in) -> Json {
    using T = std::decay_t<decltype(in)>;
    Json out = Json::object();
    out["v"] = kProtocolMajor;
    if constexpr (std::is_same_v<T, Hello>) {
      out["t"] = "hello";
      out["protocol"] = Json(in.protocol);
      out["bundle"] = Json(in.bundle);
      out["caps"] = [&] { Json a = Json::array(); for (const auto& x : in.caps) { a.push_back(Json(x)); } return a; }();
      if (in.ticket) {
        out["ticket"] = Json(*in.ticket);
      }
    } else if constexpr (std::is_same_v<T, Welcome>) {
      out["t"] = "welcome";
      out["protocol"] = Json(in.protocol);
      out["caps"] = [&] { Json a = Json::array(); for (const auto& x : in.caps) { a.push_back(Json(x)); } return a; }();
      out["graceui"] = Json(in.graceui);
      out["spaces"] = [&] { Json a = Json::array(); for (const auto& x : in.spaces) { a.push_back(encode(x)); } return a; }();
      out["session"] = Json(in.session);
    } else if constexpr (std::is_same_v<T, Sub>) {
      out["t"] = "sub";
      out["space"] = in.space;
      out["id"] = Json(in.id);
      out["topic"] = Json(in.topic);
      if (in.since) {
        out["since"] = Json(*in.since);
      }
    } else if constexpr (std::is_same_v<T, Unsub>) {
      out["t"] = "unsub";
      out["space"] = in.space;
      out["id"] = Json(in.id);
      out["topic"] = Json(in.topic);
    } else if constexpr (std::is_same_v<T, State>) {
      out["t"] = "state";
      out["space"] = in.space;
      out["topic"] = Json(in.topic);
      out["rev"] = Json(in.rev);
      out["body"] = Json(in.body);
    } else if constexpr (std::is_same_v<T, Rows>) {
      out["t"] = "rows";
      out["space"] = in.space;
      out["topic"] = Json(in.topic);
      out["from_seq"] = Json(in.from_seq);
      out["rows"] = [&] { Json a = Json::array(); for (const auto& x : in.rows) { a.push_back(Json(x)); } return a; }();
      out["dropped"] = Json(in.dropped);
    } else if constexpr (std::is_same_v<T, Cmd>) {
      out["t"] = "cmd";
      out["space"] = in.space;
      out["id"] = Json(in.id);
      out["name"] = Json(in.name);
      out["args"] = Json(in.args);
    } else if constexpr (std::is_same_v<T, Result>) {
      out["t"] = "result";
      out["space"] = in.space;
      out["id"] = Json(in.id);
      if (in.ok) {
        out["ok"] = Json(*in.ok);
      }
      if (in.error) {
        out["error"] = Json(to_string(*in.error));
      }
      if (in.body) {
        out["body"] = Json(*in.body);
      }
      if (in.detail) {
        out["detail"] = Json(*in.detail);
      }
    } else if constexpr (std::is_same_v<T, Error>) {
      out["t"] = "error";
      if (in.space) {
        out["space"] = *in.space;
      }
      out["code"] = Json(to_string(in.code));
      out["detail"] = Json(in.detail);
    } else if constexpr (std::is_same_v<T, Bye>) {
      out["t"] = "bye";
      out["reason"] = Json(to_string(in.reason));
    } else if constexpr (std::is_same_v<T, Ping>) {
      out["t"] = "ping";
    } else if constexpr (std::is_same_v<T, Pong>) {
      out["t"] = "pong";
    }
    return out;
  }, message);
}

Kind kind_of(const Message& message) noexcept { return static_cast<Kind>(message.index()); }

void encode_text(const Message& message, std::string& out) {
  out.clear();
  std::visit([&](const auto& in) {
    using T = std::decay_t<decltype(in)>;
    out += "{\"v\":";
    out += std::to_string(kProtocolMajor);
    if constexpr (std::is_same_v<T, Hello>) {
      out += ",\"t\":\"hello\"";
      append_field(out, "protocol", Json(in.protocol));
      append_field(out, "bundle", Json(in.bundle));
      out += ",\"caps\":[";
      for (std::size_t i = 0; i < (in.caps).size(); ++i) {
        if (i != 0) {
          out += ',';
        }
        append_json(out, Json((in.caps)[i]));
      }
      out += ']';
      if (in.ticket) {
        append_field(out, "ticket", Json(*in.ticket));
      }
    } else if constexpr (std::is_same_v<T, Welcome>) {
      out += ",\"t\":\"welcome\"";
      append_field(out, "protocol", Json(in.protocol));
      out += ",\"caps\":[";
      for (std::size_t i = 0; i < (in.caps).size(); ++i) {
        if (i != 0) {
          out += ',';
        }
        append_json(out, Json((in.caps)[i]));
      }
      out += ']';
      append_field(out, "graceui", Json(in.graceui));
      out += ",\"spaces\":[";
      for (std::size_t i = 0; i < (in.spaces).size(); ++i) {
        if (i != 0) {
          out += ',';
        }
        append_json(out, encode((in.spaces)[i]));
      }
      out += ']';
      append_field(out, "session", Json(in.session));
    } else if constexpr (std::is_same_v<T, Sub>) {
      out += ",\"t\":\"sub\"";
      append_field(out, "space", Json(in.space));
      append_field(out, "id", Json(in.id));
      append_field(out, "topic", Json(in.topic));
      if (in.since) {
        append_field(out, "since", Json(*in.since));
      }
    } else if constexpr (std::is_same_v<T, Unsub>) {
      out += ",\"t\":\"unsub\"";
      append_field(out, "space", Json(in.space));
      append_field(out, "id", Json(in.id));
      append_field(out, "topic", Json(in.topic));
    } else if constexpr (std::is_same_v<T, State>) {
      out += ",\"t\":\"state\"";
      append_field(out, "space", Json(in.space));
      append_field(out, "topic", Json(in.topic));
      append_field(out, "rev", Json(in.rev));
      append_field(out, "body", in.body);
    } else if constexpr (std::is_same_v<T, Rows>) {
      out += ",\"t\":\"rows\"";
      append_field(out, "space", Json(in.space));
      append_field(out, "topic", Json(in.topic));
      append_field(out, "from_seq", Json(in.from_seq));
      out += ",\"rows\":[";
      for (std::size_t i = 0; i < (in.rows).size(); ++i) {
        if (i != 0) {
          out += ',';
        }
        append_json(out, (in.rows)[i]);
      }
      out += ']';
      append_field(out, "dropped", Json(in.dropped));
    } else if constexpr (std::is_same_v<T, Cmd>) {
      out += ",\"t\":\"cmd\"";
      append_field(out, "space", Json(in.space));
      append_field(out, "id", Json(in.id));
      append_field(out, "name", Json(in.name));
      append_field(out, "args", in.args);
    } else if constexpr (std::is_same_v<T, Result>) {
      out += ",\"t\":\"result\"";
      append_field(out, "space", Json(in.space));
      append_field(out, "id", Json(in.id));
      if (in.ok) {
        append_field(out, "ok", Json(*in.ok));
      }
      if (in.error) {
        append_field(out, "error", Json(to_string(*in.error)));
      }
      if (in.body) {
        append_field(out, "body", *in.body);
      }
      if (in.detail) {
        append_field(out, "detail", Json(*in.detail));
      }
    } else if constexpr (std::is_same_v<T, Error>) {
      out += ",\"t\":\"error\"";
      if (in.space) {
        append_field(out, "space", Json(*in.space));
      }
      append_field(out, "code", Json(to_string(in.code)));
      append_field(out, "detail", Json(in.detail));
    } else if constexpr (std::is_same_v<T, Bye>) {
      out += ",\"t\":\"bye\"";
      append_field(out, "reason", Json(to_string(in.reason)));
    } else if constexpr (std::is_same_v<T, Ping>) {
      out += ",\"t\":\"ping\"";
      (void)in;
    } else if constexpr (std::is_same_v<T, Pong>) {
      out += ",\"t\":\"pong\"";
      (void)in;
    }
    out += '}';
  }, message);
}

std::string_view to_string(Command value) noexcept {
  static constexpr std::array<std::string_view, 4> kNames = {"settings.set", "settings.reset", "menu.close", "dashboard.disconnect"};
  const auto index = static_cast<std::size_t>(value);
  return index < kNames.size() ? kNames[index] : std::string_view("");
}

bool from_string(std::string_view text, Command& out) noexcept {
  static constexpr std::array<std::string_view, 4> kNames = {"settings.set", "settings.reset", "menu.close", "dashboard.disconnect"};
  for (std::size_t i = 0; i < kNames.size(); ++i) {
    if (kNames[i] == text) {
      out = static_cast<Command>(i);
      return true;
    }
  }
  return false;
}

static bool decode_settings_set(const Json& in, SettingsSetArgs& out, DecodeError& e) {
  const std::string path("args");
  if (!in.is_object()) {
    return fail(e, path, "not an object");
  }
  if (const Json* v = field(in, "key", true, path, e)) {
    const std::string p = path.empty() ? std::string("key") : path + ".key";
    if (!read_id(*v, out.key, p, e)) {
      return false;
    }
  } else if (!e.field.empty()) {
    return false;
  }
  if (const Json* v = field(in, "value", true, path, e)) {
    const std::string p = path.empty() ? std::string("value") : path + ".value";
    if (!read_json(*v, 1024u, false, out.value, p, e)) {
      return false;
    }
  } else if (!e.field.empty()) {
    return false;
  }
  return true;
}

static bool decode_settings_reset(const Json& in, SettingsResetArgs& out, DecodeError& e) {
  const std::string path("args");
  if (!in.is_object()) {
    return fail(e, path, "not an object");
  }
  if (const Json* v = field(in, "scope", true, path, e)) {
    const std::string p = path.empty() ? std::string("scope") : path + ".scope";
    if (!read_enum(*v, out.scope, p, e)) {
      return false;
    }
  } else if (!e.field.empty()) {
    return false;
  }
  if (const Json* v = field(in, "target", false, path, e)) {
    const std::string p = path.empty() ? std::string("target") : path + ".target";
    out.target.emplace();
    if (!read_id(*v, *out.target, p, e)) {
      return false;
    }
  } else if (!e.field.empty()) {
    return false;
  }
  if (const Json* v = field(in, "confirm", false, path, e)) {
    const std::string p = path.empty() ? std::string("confirm") : path + ".confirm";
    out.confirm.emplace();
    if (!read_bool(*v, *out.confirm, p, e)) {
      return false;
    }
  } else if (!e.field.empty()) {
    return false;
  }
  return true;
}

static bool decode_menu_close(const Json& in, MenuCloseArgs& out, DecodeError& e) {
  const std::string path("args");
  if (!in.is_object()) {
    return fail(e, path, "not an object");
  }
  (void)out;
  (void)e;
  return true;
}

static bool decode_dashboard_disconnect(const Json& in, DashboardDisconnectArgs& out, DecodeError& e) {
  const std::string path("args");
  if (!in.is_object()) {
    return fail(e, path, "not an object");
  }
  (void)out;
  (void)e;
  return true;
}

bool decode_args(Command command, const Json& in, CommandArgs& out, DecodeError& e) {
  switch (command) {
    case Command::settings_set: {
      SettingsSetArgs a;
      if (!decode_settings_set(in, a, e)) {
        return false;
      }
      out = std::move(a);
      return true;
    }
    case Command::settings_reset: {
      SettingsResetArgs a;
      if (!decode_settings_reset(in, a, e)) {
        return false;
      }
      out = std::move(a);
      return true;
    }
    case Command::menu_close: {
      MenuCloseArgs a;
      if (!decode_menu_close(in, a, e)) {
        return false;
      }
      out = std::move(a);
      return true;
    }
    case Command::dashboard_disconnect: {
      DashboardDisconnectArgs a;
      if (!decode_dashboard_disconnect(in, a, e)) {
        return false;
      }
      out = std::move(a);
      return true;
    }
  }
  return fail(e, "name", "not a command");
}

Json encode_args(const CommandArgs& args) {
  return std::visit([](const auto& in) -> Json {
    using T = std::decay_t<decltype(in)>;
    Json out = Json::object();
    if constexpr (std::is_same_v<T, SettingsSetArgs>) {
      out["key"] = Json(in.key);
      out["value"] = Json(in.value);
    } else if constexpr (std::is_same_v<T, SettingsResetArgs>) {
      out["scope"] = Json(to_string(in.scope));
      if (in.target) {
        out["target"] = Json(*in.target);
      }
      if (in.confirm) {
        out["confirm"] = Json(*in.confirm);
      }
    } else if constexpr (std::is_same_v<T, MenuCloseArgs>) {
      (void)in;
    } else if constexpr (std::is_same_v<T, DashboardDisconnectArgs>) {
      (void)in;
    }
    return out;
  }, args);
}

